source='''from collections import Counter

def transform(grid):
    height, width = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    marker = min(counts, key=counts.get)
    output = [row[:] for row in grid]

    for r, row in enumerate(grid):
        positions = [c for c, value in enumerate(row) if value == marker]
        if len(positions) > 1:
            for c in range(positions[0] + 1, positions[-1]):
                if grid[r][c] != marker:
                    output[r][c] = 3

    for c in range(width):
        positions = [r for r in range(height) if grid[r][c] == marker]
        if len(positions) > 1:
            for r in range(positions[0] + 1, positions[-1]):
                if grid[r][c] != marker:
                    output[r][c] = 3

    return output
